-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.anonymize_old_reports()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_n integer;
begin
  update public.content_reports r set user_id = null
   where r.user_id is not null
     and r.resolution_id in (select x.id from public.report_resolutions x
                              where x.resolved_at < now() - interval '12 months');
  get diagnostics v_n = row_count;
  return jsonb_build_object('anonymized', v_n);
end;
$function$;
